-- Synthetic fixtures never persist. No passwords, provider calls or external files.
begin;
create temp table fixture(actor uuid default gen_random_uuid(),viewer uuid default gen_random_uuid(),outsider uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),candidate uuid default gen_random_uuid(),payload jsonb default '{"titulo":"Analista SQL","descricao":"Atendimento de sistemas. Requisitos: SQL.","categoria":"regular","criteria":[{"kind":"skill","text":"SQL","min_years":null,"required":true,"weight":5,"source":"Requisitos: SQL."}]}');
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate<>expected then raise exception 'FAILED wrong SQLSTATE %: % (%)',sqlstate,name,sqlerrm;end if;insert into results values(name,true);return;end;raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,email_confirmed_at,role,aud) select id,id::text||'@job-test.invalid',now(),'authenticated','authenticated' from fixture,lateral unnest(array[actor,viewer,outsider]) id;
insert into public.companies(id,name) select company,'Jobs A' from fixture union all select other_company,'Jobs B' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'recruiter' from fixture union all select company,viewer,'viewer' from fixture union all select other_company,outsider,'owner' from fixture;
insert into public.candidates(id,company_id,processing_status,dados_extraidos) select candidate,company,'concluido','{"skills":["SQL"]}' from fixture;
update public.candidates set review_status='completed' where id=(select candidate from fixture);
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.denied('direct job insertion cannot bypass approval and audit',$q$insert into public.jobs(company_id,titulo) select company,'Bypass' from fixture$q$,'42501');
select pg_temp.denied('invalid title blocked at database',$q$select public.save_job(company,null,0,payload||'{"titulo":" "}',false) from fixture$q$,'22023');
select pg_temp.denied('unknown fields blocked',$q$select public.save_job(company,null,0,payload||'{"approved_hash":"forged"}',false) from fixture$q$,'22023');
select pg_temp.denied('empty criteria cannot be approved',$q$select public.save_job(company,null,0,payload||'{"criteria":[]}',true) from fixture$q$,'22023');
select pg_temp.denied('blank description cannot be approved',$q$select public.save_job(company,null,0,payload||'{"descricao":""}',true) from fixture$q$,'22023');
select pg_temp.denied('negative criterion weight rejected',$q$select public.save_job(company,null,0,jsonb_set(payload,'{criteria,0,weight}','-1'),true) from fixture$q$,'22023');
select pg_temp.denied('fractional weight rejected',$q$select public.save_job(company,null,0,jsonb_set(payload,'{criteria,0,weight}','1.5'),true) from fixture$q$,'22023');
select pg_temp.denied('negative experience rejected',$q$select public.save_job(company,null,0,jsonb_set(payload,'{criteria,0}',(payload->'criteria'->0)||'{"kind":"experience","min_years":-1}'),true) from fixture$q$,'22023');
select pg_temp.denied('conflicting experience rejected',$q$select public.save_job(company,null,0,payload||jsonb_build_object('criteria',jsonb_build_array((payload->'criteria'->0)||'{"kind":"experience","min_years":2}',(payload->'criteria'->0)||'{"kind":"experience","min_years":3}')),true) from fixture$q$,'22023');
select pg_temp.denied('zero experience alone insufficient',$q$select public.save_job(company,null,0,jsonb_set(payload,'{criteria,0}',(payload->'criteria'->0)||'{"kind":"experience","min_years":0}'),true) from fixture$q$,'22023');
select pg_temp.denied('stale source cannot be approved',$q$select public.save_job(company,null,0,jsonb_set(payload,'{criteria,0,source}','"No longer in the description"'),true) from fixture$q$,'22023');
select pg_temp.denied('cannot create job for another company',$q$select public.save_job(other_company,null,0,payload,true) from fixture$q$,'42501');
select set_config('test.job',(public.save_job(company,null,0,payload||jsonb_build_object('criteria',(payload->'criteria')||jsonb_build_array((payload->'criteria'->0)||'{"text":" sql ","required":false,"weight":9}')),true)->>'id'),true) from fixture;
select pg_temp.ok('duplicates merged without stacking; required wins; max weight',(select jsonb_array_length(criteria)=1 and criteria->0->>'weight'='9' and criteria->0->>'required'='true' from public.jobs where id=current_setting('test.job')::uuid));
select pg_temp.ok('creator and approver recorded',(select created_by=(select actor from fixture) and updated_by=created_by and approved_by=created_by and approved_at is not null and approved_hash is not null from public.jobs where id=current_setting('test.job')::uuid));
select pg_temp.ok('creation snapshot audited',(select count(*)=1 and bool_and(actor_id=(select actor from fixture)) from public.job_revisions where job_id=current_setting('test.job')::uuid));
select pg_temp.denied('direct edit cannot bypass revision','update public.jobs set titulo=''Bypass''','42501');
select pg_temp.denied('audit cannot be forged','delete from public.job_revisions','42501');
select public.create_job_template(company,'Analista reutilizável',payload) from fixture;
select pg_temp.ok('template keeps canonical payload and creator',(select count(*)=1 and bool_and(created_by=(select actor from fixture)) and bool_and(not(payload ? 'approved_hash')) from public.job_templates));
select pg_temp.denied('template write cannot bypass validation',$q$insert into public.job_templates(company_id,name,payload) select company,'Bypass','{}' from fixture$q$,'42501');
reset role;
set local role service_role;
select pg_temp.denied('old unversioned ranking writer retired',$q$select public.replace_job_scores(actor,company,current_setting('test.job')::uuid,'[]') from fixture$q$,'42501');
select public.replace_job_scores_v2(actor,company,j.id,j.version,j.approved_hash,jsonb_build_array(jsonb_build_object('candidate_id',candidate,'candidate_version',c.data_version,'score',100,'detalhes_matching','{}'::jsonb))) from fixture join public.jobs j on j.id=current_setting('test.job')::uuid join public.candidates c on c.id=fixture.candidate;
select pg_temp.ok('assessment stamped with approved criteria and version',(select not stale and job_version=0 and criteria_hash=(select approved_hash from public.jobs where id=current_setting('test.job')::uuid) from public.candidate_scores where job_id=current_setting('test.job')::uuid));
select set_config('test.old_hash',approved_hash,true) from public.jobs where id=current_setting('test.job')::uuid;
reset role;
set local role authenticated;
select public.save_job(company,current_setting('test.job')::uuid,0,payload||'{"descricao":"Descrição alterada para novo escopo de atuação."}',false) from fixture;
select pg_temp.ok('editing clears approval and increments version',(select version=1 and approved_hash is null and updated_by=(select actor from fixture) from public.jobs where id=current_setting('test.job')::uuid));
select pg_temp.ok('old assessment retained and stale',(select count(*)=1 and bool_and(stale) from public.candidate_scores where job_id=current_setting('test.job')::uuid));
select pg_temp.ok('audit preserves old and new description',(select before_data->>'descricao'<>after_data->>'descricao' and actor_id=(select actor from fixture) from public.job_revisions where job_id=current_setting('test.job')::uuid and version=1));
select pg_temp.denied('concurrent stale editor rejected',$q$select public.save_job(company,current_setting('test.job')::uuid,0,payload,true) from fixture$q$,'40001');
reset role;
set local role service_role;
select pg_temp.denied('stale ranking rejected even for empty results',$q$select public.replace_job_scores_v2(actor,company,current_setting('test.job')::uuid,0,current_setting('test.old_hash'),'[]') from fixture$q$,'40001');
select pg_temp.denied('draft ranking blocked at persistence',$q$select public.replace_job_scores_v2(actor,company,current_setting('test.job')::uuid,1,null,'[]') from fixture$q$,'22023');
reset role;
set local role authenticated;
select public.save_job(company,current_setting('test.job')::uuid,1,payload,true) from fixture;
select public.set_job_status(company,current_setting('test.job')::uuid,2,'encerrada') from fixture;
select pg_temp.ok('close keeps candidates and criteria',(select count(*)=1 from public.candidates) and (select status='encerrada' and version=3 and approved_hash is not null from public.jobs where id=current_setting('test.job')::uuid));
reset role;
set local role service_role;
select pg_temp.denied('closed job cannot publish a ranking',$q$select public.replace_job_scores_v2(actor,company,j.id,j.version,j.approved_hash,'[]') from fixture join public.jobs j on j.id=current_setting('test.job')::uuid$q$,'22023');
reset role;
set local role authenticated;
select public.set_job_status(company,current_setting('test.job')::uuid,3,'aberta') from fixture;
select pg_temp.ok('reopen keeps candidates and approval',(select count(*)=1 from public.candidates) and (select status='aberta' and version=4 and approved_hash is not null from public.jobs where id=current_setting('test.job')::uuid));
select pg_temp.denied('bad status blocked',$q$select public.set_job_status(company,current_setting('test.job')::uuid,4,'invalid') from fixture$q$,'22023');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',viewer,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('viewer may read company history and templates',(select count(*)=5 from public.job_revisions where job_id=current_setting('test.job')::uuid) and (select count(*)=1 from public.job_templates));
select pg_temp.denied('viewer cannot edit',$q$select public.save_job(company,current_setting('test.job')::uuid,4,payload,true) from fixture$q$,'42501');
select pg_temp.denied('viewer cannot close',$q$select public.set_job_status(company,current_setting('test.job')::uuid,4,'encerrada') from fixture$q$,'42501');
select pg_temp.denied('viewer cannot create template',$q$select public.create_job_template(company,'Forbidden',payload) from fixture$q$,'42501');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('other company cannot read history or templates',(select count(*)=0 from public.job_revisions) and (select count(*)=0 from public.job_templates));
select pg_temp.denied('company mismatch cannot edit',$q$select public.save_job(other_company,current_setting('test.job')::uuid,4,payload,true) from fixture$q$,'42501');
reset role;
delete from public.company_members where user_id=(select actor from fixture);
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.denied('revoked member cannot reuse old session',$q$select public.save_job(company,current_setting('test.job')::uuid,4,payload,true) from fixture$q$,'42501');
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) as results from results;
rollback;
